    if (typ === "unternehmen" && n.organisation?.id && ["inhaber", "admin"].includes(n.organisation.rolle) && !(db.kyc.faelle || []).some((x) => x.organisationId === n.organisation.id && x.id !== f.id)) {
      f.organisationId = n.organisation.id;
